\documentclass{article}
\usepackage{pgfplots}
\definecolor{verylightgray}{RGB}{242, 242, 242}

\begin{document}

	\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
	\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
	\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
	\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
	\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
	\definecolor{rustdeepskyblue}{rgb}{0.784,0.392,0.149}
	\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

	\pagestyle{empty}
	\begin{tikzpicture}
	\begin{axis}[
	legend pos=outer north east,
	tick label style={font=\footnotesize},
	label style={font=\small},
tick style={line width=0.8pt, color=black},
	axis line style = thick,
	axis y line = center,
	axis x line = middle,
	axis equal,
	grid = none,
	xmin = -4.75,
	xmax = 4.75,
	ymin = -6.75,
	ymax = 2.75,
	xtick = {\empty},
	%minor xtick={-11,-9,-7,-5,-3,-1,1,3,5,7,9,11},
	ytick = {-2},
	yticklabels ={$-2$},
	%%
	%% Here, we can control the positioning of each individual tick.
	y tick label style={yshift={(\tick==-2)*-6pt},xshift={(\tick==-2)*3pt}},
    %y tick label style={yshift={(\tick==-3)*-6pt}},		
	%minor ytick={-9,-7,-5,-3,-1,1,3,5,7,9,11},    
	xlabel = $x$,
	ylabel = {$y$},
	xlabel style={below right},
	ylabel style={above left},
	every axis x label/.style={
		at={(ticklabel* cs:1.02)},
		anchor=west,
	},
	every axis y label/.style={
		at={(ticklabel* cs:1.02)},
		anchor=south,
	}
	]

	\addplot [
	domain=-7:-0.1,
	samples=500,
	color=deepskyblue,
	line width=1pt,
	]{-1/x - 2};

	\addplot [
	domain=0.1:7,
	samples=500,
	color=deepskyblue,
	line width=1pt,
	]{-1/x - 2};

	\addplot [
domain=-10:10,
samples=500,
color=black,
line width=1pt,
opacity=0.25,
dashed,
]{-2};	


	\end{axis}

	\end{tikzpicture}
\end{document}

